        Describe.Lean(DescribeId.Create(id), DeclarationHandle.Create("D5/S3/Combinatorics/SpectralGraph/SixSupportFiniteRootGeometry." + name),
            H(title), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(Source),
            Blocks(Paragraph(Text(text))), DescribeRole.Theorem);
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Actual finite D-root normalization and local geometry", H("Actual finite D-root normalization and local geometry"),
        Blocks(
            Paragraph(Text("Let k be a characteristic-zero field and let K=k(b). The quadratic field H=K(sqrt(D)) and the further quadratic field F=H(sqrt(f)) use the fixed polynomials of the six-support equality curve. The finite places considered here lie above roots of D on the affine b-line. Their normalized multiplicative valuations, residue fields and ramification indices refer to the actual integral closure and its prime localizations.")),
            Item("integral-coefficients", "integral_im_polynomial", "Integral elements have polynomial imaginary coefficient", "Squarefreeness of the actual D removes the reduced denominator, proving the explicit quadratic order is the actual integral closure."),
            Item("unique-prime", "unique_prime_above", "The unique actual prime above every D root", "For each actual root in any characteristic-zero field, every actual prime above its base ideal equals the constructed kernel prime."),
            Item("uniformizer", "local_maximalIdeal", "The actual local maximal ideal is generated by y", "The localization is a genuine DVR and y is its uniformizer. The affine stalk and function field are actual Scheme/localization objects."),
            Item("valuation", "valuation_delta", "Normalized valuation of the actual base parameter", "The normalized valuation in the same H takes b-r to exp(-2) and y to exp(-1)."),
            Item("ramification", "ramification_two", "Actual ramification index two", "The library ideal-length definition of ramification index is evaluated at the actual prime/localization.")),
        [DocumentEdge.Dependency.Create(GidRef.Create("D5/S3/Combinatorics/SpectralGraph/SixSupportLaplacianPolynomial"))]));
